const ANALYSIS_LEASE_MS=15*60_000,MAX_OPPORTUNITIES=10;
const ANALYSIS_HEARTBEAT_MS=Math.floor(ANALYSIS_LEASE_MS/3);
export const SEO_PAGE_CAPTURE_ATTEMPT_DEFAULT=20,SEO_PAGE_CAPTURE_FAILURE_DEFAULT=8;
export function seoPageCaptureLimits(env:NodeJS.ProcessEnv=process.env){const bounded=(value:string|undefined,fallback:number)=>{const parsed=Number(value);return Number.isFinite(parsed)?Math.min(100,Math.max(1,Math.floor(parsed))):fallback;};const attempts=bounded(env.SEO_ACTION_PAGE_CAPTURE_ATTEMPTS,SEO_PAGE_CAPTURE_ATTEMPT_DEFAULT);return{attempts,failures:Math.min(attempts,bounded(env.SEO_ACTION_PAGE_CAPTURE_FAILURES,SEO_PAGE_CAPTURE_FAILURE_DEFAULT))};}
export const SEO_PLANNER_CANDIDATE_LIMIT=2_000;
export const SEO_COMPETING_PAGES_PER_QUERY=8;
export class SeoAnalysisInProgressError extends Error{code="ANALYSIS_IN_PROGRESS";}
export class SeoAnalysisLeaseLostError extends Error{code="ANALYSIS_LEASE_LOST";}
export function createAnalysisLeaseHeartbeat(renew:()=>Promise<boolean>,intervalMs=ANALYSIS_HEARTBEAT_MS){let lost=false,stopped=false,inFlight:Promise<void>|null=null;const heartbeat=()=>inFlight??(inFlight=renew().then(ok=>{if(!ok)lost=true;}).catch(()=>{lost=true;}).finally(()=>{inFlight=null;}));const timer=setInterval(()=>{if(!stopped)void heartbeat();},intervalMs);timer.unref?.();return{heartbeat,assertActive(){if(lost)throw new SeoAnalysisLeaseLostError("SEO analysis lease ownership was lost");},async stop(){stopped=true;clearInterval(timer);if(inFlight)await inFlight;},isLost:()=>lost};}
export function safeSeoAnalysisError(error:unknown){let current=error as {name?:unknown;message?:unknown;code?:unknown;cause?:unknown}|undefined;for(let depth=0;depth<3&&current?.cause&&typeof current.cause==="object";depth++)current=current.cause as typeof current;const name=typeof current?.name==="string"?current.name.slice(0,80):"Error",code=typeof current?.code==="string"&&/^[A-Z0-9_]{1,32}$/i.test(current.code)?current.code:undefined;let message=typeof current?.message==="string"?current.message:"Unexpected analysis failure";if(/failed query|\b(select|insert|update|delete|with)\b[\s\S]*\b(from|into|set)\b/i.test(message))message="Database operation failed";else message=message.replace(/\b(?:postgres(?:ql)?|https?):\/\/\S+/gi,"[redacted-url]").replace(/\b(?:password|token|secret|key)\s*[=:]\s*\S+/gi,"[redacted]").replace(/\s+/g," ").slice(0,240);return{name,code,message};}
type PageCaptureFailureCategory="PAGE_FETCH_FAILED"|"PAGE_SNAPSHOT_PERSIST_FAILED";
function pageCaptureFailure(category:PageCaptureFailureCategory,error:unknown){return Object.assign(new Error(category),{category,cause:error});}
export function safePageCaptureDiagnostic(error:unknown){const wrapped=error as {category?:unknown};const category:PageCaptureFailureCategory=wrapped.category==="PAGE_SNAPSHOT_PERSIST_FAILED"?"PAGE_SNAPSHOT_PERSIST_FAILED":"PAGE_FETCH_FAILED";return{category,error:safeSeoAnalysisError(error)};}
const day=(date:Date)=>date.toISOString().slice(0,10);
function seoMetricWindows(now=new Date()){const end=new Date(now);end.setUTCDate(end.getUTCDate()-3);const currentStart=new Date(end);currentStart.setUTCDate(currentStart.getUTCDate()-27);const previousStart=new Date(currentStart);previousStart.setUTCDate(previousStart.getUTCDate()-28);return{end,currentStart,previousStart};}
export type PlannerMetricLoad={current:SeoMetricRow[];previous:SeoMetricRow[];eligibleCandidates:number;loadedCandidates:number;omittedBySafetyCap:number};
/** PostgreSQL performs aggregation, eligibility, priority ordering, and LIMIT before rows enter Node. */
export async function loadPlannerMetrics(propertyId:string,now=new Date(),candidateLimit=SEO_PLANNER_CANDIDATE_LIMIT):Promise<PlannerMetricLoad>{
 const {end,currentStart,previousStart}=seoMetricWindows(now);
 const result=await db.execute(sql`WITH RECURSIVE raw_aggregated AS (
  SELECT MIN(natural_key_hash) natural_key_hash,query,page,
   COALESCE(SUM(clicks) FILTER (WHERE reporting_date >= ${day(currentStart)}),0) current_clicks,
   COALESCE(SUM(impressions) FILTER (WHERE reporting_date >= ${day(currentStart)}),0) current_impressions,
   COALESCE(SUM(position*impressions) FILTER (WHERE reporting_date >= ${day(currentStart)}),0) current_weighted,
   COALESCE(SUM(clicks) FILTER (WHERE reporting_date < ${day(currentStart)}),0) previous_clicks,
   COALESCE(SUM(impressions) FILTER (WHERE reporting_date < ${day(currentStart)}),0) previous_impressions,
   COALESCE(SUM(position*impressions) FILTER (WHERE reporting_date < ${day(currentStart)}),0) previous_weighted
  FROM seo_search_snapshots WHERE property_id=${propertyId} AND reporting_date BETWEEN ${day(previousStart)} AND ${day(end)} GROUP BY query,page
 ), canonical_hosts AS (
  SELECT natural_key_hash,lower(trim(query)) query,
   regexp_replace(regexp_replace(regexp_replace(split_part(page,'#',1),'^https?://[^/]+',lower(substring(split_part(page,'#',1) from '^https?://[^/]+')),'i'),'([?&])(utm_[^=&]+|gclid|fbclid)=[^&]*&?','\\1','gi'),'[?&]$','','g') page,
   current_clicks,current_impressions,current_weighted,previous_clicks,previous_impressions,previous_weighted FROM raw_aggregated
 ), canonicalized AS (
  SELECT natural_key_hash,query,CASE WHEN page ~* '^https?://[^/]+/$' THEN page ELSE regexp_replace(page,'/+$','','g') END page,
   current_clicks,current_impressions,current_weighted,previous_clicks,previous_impressions,previous_weighted FROM canonical_hosts
 ), aggregated AS (
  SELECT MIN(natural_key_hash) natural_key_hash,query,page,SUM(current_clicks) current_clicks,SUM(current_impressions) current_impressions,SUM(current_weighted) current_weighted,SUM(previous_clicks) previous_clicks,SUM(previous_impressions) previous_impressions,SUM(previous_weighted) previous_weighted
  FROM canonicalized GROUP BY query,page
 ), normalized_base AS (SELECT *,current_weighted/NULLIF(current_impressions,0) current_position,previous_weighted/NULLIF(previous_impressions,0) previous_position FROM aggregated), normalized AS (
  SELECT *,COUNT(*) FILTER (WHERE current_impressions>0) OVER (PARTITION BY lower(query)) current_visible_pages FROM normalized_base
 ), eligible AS (
  SELECT *,COUNT(*) OVER() eligible_count,GREATEST(
   CASE WHEN current_impressions>=50 AND current_position BETWEEN 4 AND 20 THEN current_impressions/NULLIF(current_position,0) ELSE 0 END,
   CASE WHEN current_impressions>=50 AND current_clicks/NULLIF(current_impressions,0)<(CASE WHEN current_position<=3 THEN .12 WHEN current_position<=10 THEN .04 ELSE .015 END)*.6 THEN ((CASE WHEN current_position<=3 THEN .12 WHEN current_position<=10 THEN .04 ELSE .015 END)-current_clicks/NULLIF(current_impressions,0))*current_impressions ELSE 0 END,
   CASE WHEN previous_impressions>=50 AND ((previous_clicks>0 AND current_clicks<=previous_clicks*.8) OR current_impressions<=previous_impressions*.8 OR (current_impressions>0 AND current_position>previous_position+2)) THEN GREATEST(previous_clicks-current_clicks,(previous_impressions-current_impressions)*.02,0) ELSE 0 END,
   CASE WHEN current_visible_pages>1 THEN current_impressions ELSE 0 END
  ) priority_evidence FROM normalized WHERE
   (current_impressions>=50 AND current_position BETWEEN 4 AND 20) OR
   (current_impressions>=50 AND current_clicks/NULLIF(current_impressions,0)<(CASE WHEN current_position<=3 THEN .12 WHEN current_position<=10 THEN .04 ELSE .015 END)*.6) OR
   (previous_impressions>=50 AND ((previous_clicks>0 AND current_clicks<=previous_clicks*.8) OR current_impressions<=previous_impressions*.8 OR (current_impressions>0 AND current_position>previous_position+2))) OR current_visible_pages>1
 ), eligible_queries AS (
  SELECT lower(query) normalized_query,MAX(priority_evidence) priority_evidence FROM eligible GROUP BY lower(query)
 ), query_groups AS (
  SELECT e.normalized_query,e.priority_evidence,LEAST(${SEO_COMPETING_PAGES_PER_QUERY},COUNT(*) FILTER (WHERE n.current_impressions>0 OR n.previous_impressions>=50)) expanded_rows
  FROM eligible_queries e JOIN normalized n ON lower(n.query)=e.normalized_query GROUP BY e.normalized_query,e.priority_evidence
 ), ordered_groups AS (
  SELECT *,ROW_NUMBER() OVER (ORDER BY priority_evidence DESC,normalized_query ASC) group_number FROM query_groups
 ), budgeted_queries AS (
  SELECT group_number,normalized_query,priority_evidence,expanded_rows,expanded_rows used_rows,true included FROM ordered_groups WHERE group_number=1 AND expanded_rows<=${candidateLimit}
  UNION ALL
  SELECT n.group_number,n.normalized_query,n.priority_evidence,n.expanded_rows,b.used_rows+CASE WHEN b.used_rows+n.expanded_rows<=${candidateLimit} THEN n.expanded_rows ELSE 0 END,b.used_rows+n.expanded_rows<=${candidateLimit}
  FROM budgeted_queries b JOIN ordered_groups n ON n.group_number=b.group_number+1
 ), selected_queries AS (
  SELECT normalized_query,priority_evidence FROM budgeted_queries WHERE included
 ), expanded AS (
  SELECT n.*,s.priority_evidence,ROW_NUMBER() OVER (PARTITION BY lower(n.query) ORDER BY (n.current_impressions>0) DESC,n.current_impressions DESC,n.previous_impressions DESC,n.natural_key_hash ASC) page_rank
  FROM normalized n JOIN selected_queries s ON lower(n.query)=s.normalized_query WHERE n.current_impressions>0 OR n.previous_impressions>=50
 ) SELECT *,(SELECT COUNT(*) FROM eligible) eligible_count FROM expanded WHERE page_rank<=${SEO_COMPETING_PAGES_PER_QUERY}
 ORDER BY priority_evidence DESC,current_impressions DESC,previous_impressions DESC,natural_key_hash ASC LIMIT ${candidateLimit}`);
 const rows=result.rows as Record<string,unknown>[],metric=(r:Record<string,unknown>,prefix:"current"|"previous"):SeoMetricRow=>{const impressions=Number(r[`${prefix}_impressions`]);return{query:String(r.query),page:String(r.page),clicks:Number(r[`${prefix}_clicks`]),impressions,position:impressions?Number(r[`${prefix}_weighted`])/impressions:0}};const eligibleCandidates=Number(rows[0]?.eligible_count??0);return{current:rows.map(r=>metric(r,"current")),previous:rows.map(r=>metric(r,"previous")),eligibleCandidates,loadedCandidates:rows.length,omittedBySafetyCap:Math.max(0,eligibleCandidates-rows.length)};
}
export function hasRawCurrentActionEvidence(rows:SeoMetricRow[],targetPage:string,queryCluster:string[]){const target=normalizeSeoPageIdentity(targetPage),queries=new Set(queryCluster.map(query=>query.trim().toLowerCase()));return aggregateNormalizedMetricRows(rows).some(row=>row.impressions>0&&row.page===target&&queries.has(row.query));}
/** Reads the current window before opportunity thresholds are applied. Query failures propagate as refresh failures. */
export async function loadRawCurrentActionEvidence(propertyId:string,targetPage:string,queryCluster:string[],now=new Date()){const {end,currentStart}=seoMetricWindows(now),queries=[...new Set(queryCluster.map(query=>query.trim().toLowerCase()).filter(Boolean))];if(!queries.length)return false;const result=await db.execute(sql`SELECT query,page,SUM(clicks) clicks,SUM(impressions) impressions,SUM(position*impressions)/NULLIF(SUM(impressions),0) position FROM seo_search_snapshots WHERE property_id=${propertyId} AND reporting_date BETWEEN ${day(currentStart)} AND ${day(end)} AND lower(trim(query)) IN (${sql.join(queries.map(query=>sql`${query}`),sql`,`)}) GROUP BY query,page`);const rows=(result.rows as Record<string,unknown>[]).map(row=>({query:String(row.query),page:String(row.page),clicks:Number(row.clicks),impressions:Number(row.impressions),position:Number(row.position)||0}));return hasRawCurrentActionEvidence(rows,targetPage,queries);}
type FreshProposalEvidence={fingerprint:string;title:string|null;metaDescription:string|null;headings:unknown;sections?:unknown;competitorCount:number;capturedAt?:Date|string};
const cleanText=(value:unknown)=>typeof value==="string"?value.replace(/\s+/g," ").trim():"";
const truncate=(value:string,max:number)=>value.length<=max?value:`${value.slice(0,max-1).replace(/\s+\S*$/,"").trim()}…`;
export class InsufficientSeoEvidenceError extends Error{category="INSUFFICIENT_EVIDENCE";}
type DecisiveIntent="pricing"|null;
export function decisiveIntentForQuery(query:string):DecisiveIntent{return /(?:\b(?:pricing|prices?|costs?|precio|precios|costo|coste|tarifa|tarifas)\b|מחיר|מחירים|עלות)/iu.test(query)?"pricing":null;}
export function evidenceAnswersDecisiveIntent(intent:DecisiveIntent,evidence:string){if(!intent)return true;if(intent==="pricing")return /(?:[$€£₪]\s*\d|\d(?:[\d.,]*\d)?\s*(?:[$€£₪]|usd|eur|gbp|ils|dollars?|euros?|shekels?|per\s+(?:month|year|user)|al\s+mes|por\s+(?:mes|año|usuario)|לחודש|לשנה|למשתמש)|(?:free|gratis|gratuito|חינם)\s+(?:plan|tier|trial|plan gratuito|תוכנית|ניסיון)|(?:contact sales|request (?:a )?quote|consulta (?:una )?cotización|solicita (?:una )?cotización|צור קשר לקבלת הצעת מחיר))/iu.test(evidence);return false;}
export function buildProposal(item:ScoredOpportunity,fresh?:FreshProposalEvidence){
 if(item.type==="cannibalization"&&!hasMaterialCannibalizationEvidence(item))throw new InsufficientSeoEvidenceError("Cannibalization requires at least two material competing pages");
 if(!fresh)throw new InsufficientSeoEvidenceError("A current first-party page snapshot is required");
 const title=cleanText(fresh.title),currentMeta=cleanText(fresh.metaDescription),headings=Array.isArray(fresh.headings)?fresh.headings.map(cleanText).filter(Boolean):[],body=Array.isArray(fresh.sections)?fresh.sections.map(cleanText).join(" "):cleanText(fresh.sections);
 if(!title||(!body&&!headings.length))throw new InsufficientSeoEvidenceError("The first-party snapshot does not contain enough page content");
 const rawQuery=item.queryCluster[0]??"",query=queryForTargetPage(rawQuery,item.targetPage??"/"),actionType=actionTypeForItem(item);
 if(actionType==="meta_description"&&item.current.position>20)throw new InsufficientSeoEvidenceError("Low CTR at a low ranking position is visibility evidence, not a plausible snippet problem");
 const pageFacts=truncate(body||headings.join(". "),180),currentValue=actionType==="meta_description"?(currentMeta||"No meta description present"):truncate(`${headings.join(" | ")} — ${body}`,600);
 const dateRange="Current 28-day Search Console window compared with the preceding 28 days (ending after the standard 3-day reporting lag)";
 const limitations=`Search Console is observational and does not prove causation. ${fresh.competitorCount?`${fresh.competitorCount} stored competitor snapshot(s) were available; no claim is made that they are comprehensive.`:"No competitor research was available or analyzed."}`;
 let proposedMetaDescription:string|null=null,proposedContent:string|null=null,contentBrief:string|null=null,insertionLocation:string,implementationTarget:string,observedProblem:string,rationale:string;
 if(actionType==="meta_description"){
  const intent=title.replace(/\s*[|–—-]\s*Whachat(?:CRM)?\b.*$/iu,"").trim();
  proposedMetaDescription=truncate(`${intent}: ${pageFacts}`,160);
  if(!currentMeta)observedProblem=`The current first-party snapshot has no meta description for a query with ${item.current.impressions} impressions at average position ${item.current.position.toFixed(1)}.`;
  else observedProblem=`The current description does not clearly connect the page-specific content to “${query}” despite ${item.current.impressions} impressions at average position ${item.current.position.toFixed(1)}.`;
  rationale="The replacement leads with the verified page topic and summarizes first-party content, making the snippet more specific without adding unsupported claims.";
  insertionLocation="Replace meta description";implementationTarget="The meta description in the HTML <head> for this exact URL";
 }else if(item.type==="cannibalization"){
  contentBrief=`Compare the ${item.competingPages.length} materially visible pages and choose one owner for “${query}”. Preserve the original pages until intent, links, and conversion paths are reviewed.`;
  observedProblem=item.reason;rationale="A human ownership decision is required before any consolidation; the evidence does not justify an automatic redirect, canonical, deletion, or rewrite.";
  insertionLocation="No content insertion; resolve page ownership in a focused implementation PR";implementationTarget="Routing, canonical metadata, and internal links for the materially competing URLs";
 }else{
  const targetPage=item.targetPage??"/",language=recommendationLanguageForPage(targetPage),cleanRawQuery=rawQuery.replace(/[\u0000-\u001f\u007f]+/gu," ").replace(/\s+/gu," ").trim();
  if(!cleanRawQuery||query!==cleanRawQuery||!recommendationTextMatchesPageLanguage(query,targetPage))throw new InsufficientSeoEvidenceError("The Search Console query does not match the target page language, so a safe content heading cannot be produced");
  if(!recommendationTextMatchesPageLanguage(`${title} ${body}`,targetPage))throw new InsufficientSeoEvidenceError("The first-party snapshot does not contain enough content in the target page language");
  const coverageStopWords=new Set(["with","from","that","this","your","into","what","when","where","which","does","have","after","happens","arrives","como","cómo","para","esta","este","cuando","después","sucede","llega","donde","cuál","qué","איך","מה","אחרי","קורה","מגיעה","מתי","איפה","הזה","הזאת"]),genericWords=new Set(["whatsapp","crm","page","página","עמוד"]),words=(value:string)=>value.toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(word=>word.length>2&&!coverageStopWords.has(word)),queryTokens=words(query),isQuestion=/^(?:what|how|why|when|where|which|can|does|is|qué|cómo|cuándo|dónde|cuál|מה|איך|מתי|איפה)(?:\s|$)/iu.test(query),covered=body.toLowerCase().includes(query.toLowerCase())||(!isQuestion&&queryTokens.length>0&&queryTokens.every(word=>body.toLowerCase().includes(word)));
  if(covered)throw new InsufficientSeoEvidenceError("The requested topic is already adequately represented in the first-party snapshot");
  const anchors=queryTokens.filter(word=>!genericWords.has(word)),stem=(word:string)=>word.slice(0,Math.min(word.length,6)),sentences=body.split(/(?<=[.!?。！？])\s+/u).map(value=>value.trim()).filter(value=>value.length>=20),decisiveIntent=decisiveIntentForQuery(query),relevant=sentences.map(sentence=>({sentence,score:anchors.filter(anchor=>words(sentence).some(word=>stem(word)===stem(anchor))).length})).filter(row=>row.score>0&&evidenceAnswersDecisiveIntent(decisiveIntent,row.sentence)).sort((a,b)=>b.score-a.score).slice(0,2);
  if(decisiveIntent&&!sentences.some(sentence=>evidenceAnswersDecisiveIntent(decisiveIntent,sentence)))throw new InsufficientSeoEvidenceError(`The snapshot does not contain a verified ${decisiveIntent} answer for “${query}”`);
  const requiredMatches=Math.max(1,Math.ceil(anchors.length/2));if(!anchors.length||!relevant.length||relevant[0].score<requiredMatches)throw new InsufficientSeoEvidenceError(`The snapshot does not contain verified facts that answer “${query}”`);
  const heading=language==="he"?query:query.replace(/^(.)/u,letter=>letter.toUpperCase()),lead={en:"The verified workflow described on this page is:",es:"El flujo verificado descrito en esta página es:",he:"התהליך המאומת המתואר בעמוד הוא:"}[language],answer=relevant.map(row=>row.sentence).join(" ");
  proposedContent=`## ${heading}\n\n${lead} ${answer}`;
  if(!recommendationTextMatchesPageLanguage(proposedContent,targetPage))throw new InsufficientSeoEvidenceError("The grounded draft could not be produced in the target page language");
  observedProblem=`The first-party snapshot does not directly answer “${query}”; the query has ${item.current.impressions} impressions, while related verified facts are present elsewhere on the page.`;
  rationale="The draft answers the identified question using only the most relevant verified first-party facts, rather than copying the opening body text or inferring unsupported details.";
  insertionLocation=headings.length?`Add a new section after “${headings.at(-1)}”`:`Add a new section after the primary product overview`;implementationTarget="The body content of this exact URL at the named section boundary";
 }
 return validateRecommendationOutput({actionType,proposedMetaDescription,proposedContent,contentBrief,insertionLocation,implementationTarget,observedProblem,currentValue,rationale,evidenceSummary:`${item.reason} Diagnostic Search Console query: “${truncate(rawQuery,200)}”. First-party snapshot ${fresh.fingerprint.slice(0,12)}: title “${truncate(title,120)}”; ${headings.length} captured heading(s).`,evidenceDateRange:dateRange,evidenceLimitations:limitations,repositoryTarget:null,acceptanceChecks:["The deployed value exactly matches the approved proposal.","The page remains indexable and its canonical URL is unchanged.","A fresh first-party snapshot verifies the value after deployment."],explanation:`${observedProblem} ${rationale}`.slice(0,2_000),expectedBenefit:"Improve alignment between the verified page content and the demonstrated search intent; no uplift is estimated.",confidence:item.confidenceScore,risk:item.type==="cannibalization"?"high":"medium",automaticExecutionEligible:false,rollbackConcept:`Restore the value from first-party snapshot ${fresh.fingerprint.slice(0,12)}.`,evidenceIds:[item.clusterKey,`page:${fresh.fingerprint}`]});
}
function actionTypeForItem(item:ScoredOpportunity){return item.type==="low_ctr"?"meta_description":item.type==="cannibalization"?"cannibalization":"content_expansion";}
function actionIdentity(propertyId:string,item:ScoredOpportunity){const actionType=actionTypeForItem(item);return{key:recommendationIdempotencyKey(propertyId,item.targetPage!,item.queryCluster,actionType)};}
type OpenActionIdentity={id:string;idempotencyKey:string;targetPage:string;contentFingerprint:string;status:string;currentVersion:number;staleCheckedAt:Date|null;staleCheckRetryAt:Date|null};
async function loadOpenActions(propertyId:string,keys:string[]){if(!keys.length)return[];const result=await db.execute(sql`SELECT a.id,a.idempotency_key,a.target_page,a.original_content_fingerprint,a.status,a.current_version,a.stale_checked_at,a.stale_check_retry_at FROM seo_actions a JOIN seo_action_versions v ON v.action_id=a.id AND v.version=a.current_version WHERE a.property_id=${propertyId} AND a.status IN ('detected','researching','proposed','approved','revision_required','rejected') AND a.idempotency_key IN (${sql.join(keys.map(key=>sql`${key}`),sql`,`)}) ORDER BY a.updated_at ASC,a.id ASC LIMIT ${SEO_PLANNER_CANDIDATE_LIMIT}`);return(result.rows as Record<string,unknown>[]).map(row=>({id:String(row.id),idempotencyKey:String(row.idempotency_key),targetPage:String(row.target_page),contentFingerprint:String(row.original_content_fingerprint),status:String(row.status),currentVersion:Number(row.current_version),staleCheckedAt:row.stale_checked_at?new Date(String(row.stale_checked_at)):null,staleCheckRetryAt:row.stale_check_retry_at?new Date(String(row.stale_check_retry_at)):null}));}
async function loadStaleCheckQueue(propertyId:string){const result=await db.execute(sql`SELECT a.id,a.idempotency_key,a.target_page,a.original_content_fingerprint,a.status,a.current_version,a.stale_checked_at,a.stale_check_retry_at FROM seo_actions a JOIN seo_action_versions v ON v.action_id=a.id AND v.version=a.current_version WHERE a.property_id=${propertyId} AND a.status IN ('proposed','approved') AND (a.stale_check_retry_at IS NULL OR a.stale_check_retry_at<=NOW()) ORDER BY a.stale_checked_at ASC NULLS FIRST,a.id ASC LIMIT ${SEO_STALE_CHECK_LIMIT}`);return(result.rows as Record<string,unknown>[]).map(row=>({id:String(row.id),idempotencyKey:String(row.idempotency_key),targetPage:String(row.target_page),contentFingerprint:String(row.original_content_fingerprint),status:String(row.status),currentVersion:Number(row.current_version),staleCheckedAt:row.stale_checked_at?new Date(String(row.stale_checked_at)):null,staleCheckRetryAt:row.stale_check_retry_at?new Date(String(row.stale_check_retry_at)):null}));}
export const SEO_STALE_CHECK_LIMIT=10;
export const SEO_STALE_RETRY_MS=15*60_000;
export const SEO_LEGACY_REFRESH_RECOVERY_LIMIT=50;
export function recoveredRefreshStatus(returnStatus:unknown,staleAt:unknown){return ["proposed","revision_required","rejected"].includes(String(returnStatus))?String(returnStatus):staleAt?"revision_required":"proposed";}
