export const SEO_ACTION_REFRESH_LEASE_DEFAULT_MS=5*60_000;
export function seoActionRefreshLeaseMs(env:NodeJS.ProcessEnv=process.env){const parsed=Number(env.SEO_ACTION_REFRESH_LEASE_MS);return Number.isFinite(parsed)?Math.min(30*60_000,Math.max(60_000,Math.floor(parsed))):SEO_ACTION_REFRESH_LEASE_DEFAULT_MS;}
