   await tx.insert(seoActionEvents).values({actionId:id,fromStatus:"researching",toStatus:"proposed",actorId,safeMetadata:{refresh:true,version:next,recoveredExpiredClaim:claim.recovered,refreshedOpportunityId:refreshedOpportunity.id}});
